import random, math
from collections import Counter, defaultdict

CT = "SALKMSKXZYRZEJFEOTMBRRZBRXYCXPNJIIWDRYADAIWKKKBEBUDDGNCXTUUBSJXMQVIVPVBYQEVVRBXMTEFGHRVULFEJZZUTXZIVBABSKQESEWKPKGXNVGTZHIFVWLCAQDHOKIGZZRV"
FREQ=[0.08167,0.01492,0.02782,0.04253,0.12702,0.02228,0.02015,0.06094,0.06966,0.00153,
0.00772,0.04025,0.02406,0.06749,0.07507,0.01929,0.00095,0.05987,0.06327,0.09056,
0.02758,0.00978,0.02360,0.00150,0.01974,0.00074]

# ---------- dictionaries ----------
COMMON = [w.strip().upper() for w in open('common20k.txt') if w.strip()]
COMMON_SET = set(COMMON)
RANK = {w: i for i, w in enumerate(COMMON)}
ALLW = set(w.strip().upper() for w in open('words.txt') if w.strip())

# ---------- quadgram model from wordlists ----------
qcount = defaultdict(float)
def add_word(w, weight):
    s = '^' + w + '$'
    for i in range(len(s) - 3):
        qcount[s[i:i+4]] += weight
for i, w in enumerate(COMMON):
    add_word(w, max(1.0, (len(COMMON) - i) / 50.0))
for w in ALLW:
    if 3 <= len(w) <= 15:
        add_word(w, 0.3)
tot = sum(qcount.values())
QLOG = {k: math.log(v / tot) for k, v in qcount.items()}
FLOOR = math.log(0.01 / tot)

def qscore(s):
    s = '^' + s + '$'
    return sum(QLOG.get(s[i:i+4], FLOOR) for i in range(len(s) - 3)) / len(s)

# ---------- segmentation judge ----------
MAXW = 18
def segment_score(s):
    # DP: best score to segment s into common words; score = sum of len^2, small penalty per word
    n = len(s)
    best = [-1e9] * (n + 1); best[0] = 0; back = [None] * (n + 1)
    for i in range(n):
        if best[i] == -1e9: continue
        for L in range(2, MAXW + 1):
            j = i + L
            if j > n: break
            w = s[i:j]
            if w in COMMON_SET:
                sc = best[i] + L * L - 1
                if sc > best[j]:
                    best[j] = sc; back[j] = i
    if best[n] == -1e9: return -1e9, ''
    # reconstruct
    out = []; i = n
    while i > 0:
        j = back[i]; out.append(s[j:i]); i = j
    out.reverse()
    return best[n] / (n * n), ' '.join(out)

# ---------- ciphers ----------
def decrypt(ct, key, mode):
    out = []; L = len(key)
    for i, ch in enumerate(ct):
        c = ord(ch) - 65; k = key[i % L]
        if mode == 0: p = (c - k) % 26
        elif mode == 1: p = (k - c) % 26
        else: p = (c + k) % 26
        out.append(chr(65 + p))
    return ''.join(out)

def chi_key(ct, mode, L):
    cols = [ct[i::L] for i in range(L)]
    key = []; tot = 0.0
    for col in cols:
        cnt = Counter((ord(ch) - 65) % 26 for ch in col)
        n = len(col); bb = (1e18, 0)
        for k in range(26):
            t = 0.0
            for i in range(26):
                if mode == 0: p = (i - k) % 26
                elif mode == 1: p = (k - i) % 26
                else: p = (i + k) % 26
                obs = cnt.get(p, 0); exp = FREQ[i] * n
                t += (obs - exp) ** 2 / exp
            if t < bb[0]: bb = (t, k)
        key.append(bb[1]); tot += bb[0]
    return key, tot / len(ct)

def hillclimb(ct, mode, L, restarts=8, iters=40):
    bestg = (-1e18, None)
    for r in range(restarts):
        if r == 0:
            key, _ = chi_key(ct, mode, L)
        else:
            key = [random.randrange(26) for _ in range(L)]
        cur = qscore(decrypt(ct, key, mode))
        improved = True
        while improved:
            improved = False
            for pos in range(L):
                for k in range(26):
                    if k == key[pos]: continue
                    nk = key[:]; nk[pos] = k
                    sc = qscore(decrypt(ct, nk, mode))
                    if sc > cur:
                        cur = sc; key = nk; improved = True
        bestg = max(bestg, (cur, key))
    return bestg

# ---------- transposition variants ----------
def rail_pat(n, rails):
    pat = []; r = 0; d = 1
    for i in range(n):
        pat.append(r); r += d
        if rails > 1 and r == rails - 1: d = -1
        if rails > 1 and r == 0: d = 1
    return pat
def rail_enc(s, rails):
    pat = rail_pat(len(s), rails)
    return ''.join(s[i] for i in sorted(range(len(s)), key=lambda i: pat[i]))
def rail_dec(s, rails):
    pat = rail_pat(len(s), rails)
    order = sorted(range(len(s)), key=lambda i: pat[i])
    out = [''] * len(s)
    for k, i in enumerate(order): out[i] = s[k]
    return ''.join(out)
def colar_enc(s, key):
    n = len(key)
    rows = [s[i:i+n] for i in range(0, len(s), n)]
    order = sorted(range(n), key=lambda k: key[k])
    return ''.join(row[c] for c in order for row in rows if c < len(row))
def colar_dec(s, key):
    n = len(key); nrows = (len(s) + n - 1) // n
    order = sorted(range(n), key=lambda k: key[k])
    cols = {}; idx = 0
    for c in order:
        ln = len([r for r in range(nrows) if r * n + c < len(s)])
        cols[c] = s[idx:idx+ln]; idx += ln
    out = ''
    for r in range(nrows):
        for c in range(n):
            if r * n + c < len(s) and r < len(cols[c]): out += cols[c][r]
    return out

V = {'identity': CT, 'reverse': CT[::-1]}
tri = ''.join(CT[i:i+3][::-1] for i in range(0, len(CT), 3))
V['trios_rev'] = tri
V['trios_rev_wholerev'] = tri[::-1]
V['trios_rot1'] = ''.join(CT[i+1:i+3] + CT[i:i+1] for i in range(0, len(CT), 3))
V['trios_rot2'] = ''.join(CT[i+2:i+3] + CT[i:i+2] for i in range(0, len(CT), 3))
V['trios_swap_ends'] = ''.join(CT[i+2] + CT[i+1] + CT[i] if i + 2 < len(CT) else CT[i:] for i in range(0, len(CT), 3))
for r in range(2, 6):
    V[f'railE{r}'] = rail_enc(CT, r); V[f'railD{r}'] = rail_dec(CT, r)
for key in ['LOCK', 'SEEN', 'GRANITE', 'IRON', 'GUY', 'STONE', 'VAULT', 'MIDNIGHT', 'TEMPLE', 'REMEMBER', 'GUYSEEN', 'SEENREMEMBERTHEGUY']:
    V[f'colE_{key}'] = colar_enc(CT, key); V[f'colD_{key}'] = colar_dec(CT, key)
for off in range(3):
    V[f'ilv3_{off}'] = CT[off::3] + ''.join(CT[(off + j) % 3::3] for j in (1, 2))

# ---------- stage 1: chi ranking ----------
stage1 = []
for name, c in V.items():
    for mode in (0, 1, 2):
        for L in range(1, 21):
            key, sc = chi_key(c, mode, L)
            stage1.append((sc, name, mode, L, key))
stage1.sort()
print("chi top 10:")
for s in stage1[:10]: print(f"  {s[0]:.3f} {s[1]} mode={s[2]} L={s[3]}")

# ---------- stage 2: hillclimb top 120 combos ----------
cands = stage1[:120]
res = []
for sc, name, mode, L, key in cands:
    c = V[name]
    qs, k2 = hillclimb(c, mode, L, restarts=4, iters=40)
    pt = decrypt(c, k2, mode)
    seg, segpt = segment_score(pt)
    res.append((seg, qs, name, mode, L, ''.join(chr(65 + x) for x in k2), pt, segpt))
res.sort(reverse=True)
print("\nTOP by segmentation:")
for r in res[:12]:
    print(f"seg={r[0]:.3f} q={r[1]:.3f} {r[2]} mode={r[3]} L={r[4]} key={r[5]}")
    print("   pt:", r[6])
    if r[7]: print("   seg:", r[7][:150])

